class IPAddress:
    VALID_OCTET_COUNT = 4
    OCTET_MAX_VALUE = 255
    BINARY_FORMAT = '08b'
    OCTET_SEPARATOR = '.'

    def __init__(self, ip_address):
        self.ip_address = ip_address

    def is_valid(self):
        octets = self.ip_address.split(self.OCTET_SEPARATOR)
        if len(octets) != self.VALID_OCTET_COUNT:
            return False
        for octet in octets:
            if not self.is_valid_octet(octet):
                return False
        return True

    def is_valid_octet(self, octet):
        return octet.isdigit() and 0 <= int(octet) <= self.OCTET_MAX_VALUE

    def get_octets(self):
        return self.ip_address.split(self.OCTET_SEPARATOR) if self.is_valid() else []

    def get_binary(self):
        return self._validate_and_convert_to_binary()

    def _validate_and_convert_to_binary(self):
        if not self.is_valid():
            return ''
        return self._build_binary_representation(self.get_octets())

    def _build_binary_representation(self, octets):
        binary_octets = [self._format_octet_to_binary(octet) for octet in octets]
        return self.OCTET_SEPARATOR.join(binary_octets)

    def _format_octet_to_binary(self, octet):
        return format(int(octet), self.BINARY_FORMAT)
